    public static func addSubtract<S, T, U, V>(_ vectorA: S, _ vectorB: T, addResult: inout U, subtractResult: inout V)
        where S: AccelerateBuffer, T: AccelerateBuffer, U: AccelerateMutableBuffer, V: AccelerateMutableBuffer,
              S.Element == Float, T.Element == Float, U.Element == Float, V.Element == Float {
        let n = min(vectorA.count, vectorB.count, addResult.count, subtractResult.count)
        guard n > 0 else { return }
        vectorA.withUnsafeBufferPointer { a in vectorB.withUnsafeBufferPointer { b in
            addResult.withUnsafeMutableBufferPointer { s in subtractResult.withUnsafeMutableBufferPointer { d in
                vDSP_vaddsub(b.baseAddress!, 1, a.baseAddress!, 1, s.baseAddress!, 1, d.baseAddress!, 1, vDSP_Length(n))
            } } } }
    }
