    public static func stereoRamp<U>(withInitialValue initialValue: inout Float, multiplyingBy multiplierOne: U, _ multiplierTwo: U, increment: Float)
        -> (firstOutput: [Float], secondOutput: [Float]) where U: AccelerateBuffer, U.Element == Float {
