    public static func integrate<U, V>(_ vector: U, using rule: IntegrationRule, stepSize: Float = 1, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Float, V.Element == Float {
        var h = stepSize
        let n = min(vector.count, result.count); guard n > 0 else { return }
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            switch rule {
            case .runningSum: vDSP_vrsum(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            case .simpson: vDSP_vsimps(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            case .trapezoidal: vDSP_vtrapz(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            }
        } }
    }
