    public static func normalize(_ vector: some AccelerateBuffer<Float>, result: inout some AccelerateMutableBuffer<Float>) -> (mean: Float, stdDev: Float) {
        var m: Float = 0, s: Float = 0
        let n = min(vector.count, result.count)
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            if n > 0 { vDSP_normalize(a.baseAddress!, 1, c.baseAddress!, 1, &m, &s, vDSP_Length(n)) } } }
        return (m, s)
    }
    public static func normalize(_ vector: some AccelerateBuffer<Float>) -> [Float] {
