    public static func threshold<U, V>(_ vector: U, to lowerBound: Float, with rule: ThresholdRule<Float>, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Float, V.Element == Float {
        var b = lowerBound
        let n = min(vector.count, result.count); guard n > 0 else { return }
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            switch rule {
            case .clampToThreshold: vDSP_vthr(a.baseAddress!, 1, &b, c.baseAddress!, 1, vDSP_Length(n))
            case .zeroFill: vDSP_vthres(a.baseAddress!, 1, &b, c.baseAddress!, 1, vDSP_Length(n))
            case .signedConstant(let k): var k = k; vDSP_vthrsc(a.baseAddress!, 1, &b, &k, c.baseAddress!, 1, vDSP_Length(n))
            }
        } }
    }
