    /// y[n] = b0 x[n] + b1 x[n-1] + b2 x[n-2] - a1 y[n-1] - a2 y[n-2] (coefficients (b0, b1, b2, a1, a2)); the first two
    /// outputs are the initial state
    public static func twoPoleTwoZeroFilter<U, V>(_ source: U, coefficients: (Float, Float, Float, Float, Float), result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Float, V.Element == Float {
        let n = min(source.count, result.count); guard n > 2 else { return }
        var c = [coefficients.0, coefficients.1, coefficients.2, coefficients.3, coefficients.4]
        source.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { r in vDSP_deq22(a.baseAddress!, 1, &c, r.baseAddress!, 1, vDSP_Length(n - 2)) } }
    }
    public static func twoPoleTwoZeroFilter<U>(_ source: U, coefficients: (Float, Float, Float, Float, Float)) -> [Float] where U: AccelerateBuffer, U.Element == Float {
        var r = [Float](repeating: 0, count: source.count)
        twoPoleTwoZeroFilter(source, coefficients: coefficients, result: &r)
        return r
    }
    public static func formWindow<V>(usingSequence sequence: WindowSequence, result: inout V, isHalfWindow: Bool) where V: AccelerateMutableBuffer, V.Element == Float {
        let w = window(ofType: Float.self, usingSequence: sequence, count: result.count, isHalfWindow: isHalfWindow)
        result.withUnsafeMutableBufferPointer { r in for i in 0..<min(r.count, w.count) { r[i] = w[i] } }
    }

