        guard n > 0 else { return }
        vectorA.withUnsafeBufferPointer { a in vectorB.withUnsafeBufferPointer { b in
            addResult.withUnsafeMutableBufferPointer { s in subtractResult.withUnsafeMutableBufferPointer { d in
                vDSP_vaddsubD(b.baseAddress!, 1, a.baseAddress!, 1, s.baseAddress!, 1, d.baseAddress!, 1, vDSP_Length(n))
            } } } }
    }
