    public static func countZeroCrossings<U>(_ vector: U) -> UInt where U: AccelerateBuffer, U.Element == Double {
        var last: vDSP_Length = 0, count: vDSP_Length = 0
        vector.withUnsafeBufferPointer { a in if let p = a.baseAddress { vDSP_nzcrosD(p, 1, vDSP_Length(a.count), &last, &count, vDSP_Length(a.count)) } }
        return count
    }
    public static func downsample<T, U, V>(_ source: U, decimationFactor: Int, filter: T, result: inout V)
        where T: AccelerateBuffer, U: AccelerateBuffer, V: AccelerateMutableBuffer, T.Element == Double, U.Element == Double, V.Element == Double {
        let n = result.count, p = filter.count
        precondition(source.count >= (n - 1) * decimationFactor + p, "vDSP.downsample: the source is too short")
        source.withUnsafeBufferPointer { a in filter.withUnsafeBufferPointer { f in result.withUnsafeMutableBufferPointer { r in
            vDSP_desampD(a.baseAddress!, decimationFactor, f.baseAddress!, r.baseAddress!, vDSP_Length(n), vDSP_Length(p)) } } }
    }
    public static func downsample<T, U>(_ source: U, decimationFactor: Int, filter: T) -> [Double] where T: AccelerateBuffer, U: AccelerateBuffer, T.Element == Double, U.Element == Double {
        let n = (source.count - filter.count) / decimationFactor + 1
        return _array(max(n, 0)) { downsample(source, decimationFactor: decimationFactor, filter: filter, result: &$0) }
    }
    public static func evaluatePolynomial<U, V>(usingCoefficients coefficients: [Double], withVariables variables: U, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        let n = min(variables.count, result.count); guard n > 0, !coefficients.isEmpty else { return }
        variables.withUnsafeBufferPointer { b in result.withUnsafeMutableBufferPointer { c in
            vDSP_vpolyD(coefficients, 1, b.baseAddress!, 1, c.baseAddress!, 1, vDSP_Length(n), vDSP_Length(coefficients.count - 1)) } }
    }
    public static func evaluatePolynomial<U>(usingCoefficients coefficients: [Double], withVariables variables: U) -> [Double] where U: AccelerateBuffer, U.Element == Double {
        _array(variables.count) { evaluatePolynomial(usingCoefficients: coefficients, withVariables: variables, result: &$0) }
    }
    public static func formRamp<V>(withInitialValue initialValue: Double, increment: Double, result: inout V) where V: AccelerateMutableBuffer, V.Element == Double {
        var a = initialValue, b = increment
        let n = result.count
        result.withUnsafeMutableBufferPointer { r in vDSP_vrampD(&a, &b, r.baseAddress!, 1, vDSP_Length(n)) }
    }
    public static func formRamp<V>(from start: Double, through end: Double, result: inout V) where V: AccelerateMutableBuffer, V.Element == Double {
        var a = start, b = end
        let n = result.count
        result.withUnsafeMutableBufferPointer { r in vDSP_vgenD(&a, &b, r.baseAddress!, 1, vDSP_Length(n)) }
    }
    public static func formRamp<V>(in range: ClosedRange<Double>, result: inout V) where V: AccelerateMutableBuffer, V.Element == Double {
        formRamp(from: range.lowerBound, through: range.upperBound, result: &result)
    }
    public static func formRamp<U, V>(withInitialValue initialValue: inout Double, multiplyingBy vector: U, increment: Double, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        var step = increment
        let n = min(vector.count, result.count); guard n > 0 else { return }
        vector.withUnsafeBufferPointer { i in result.withUnsafeMutableBufferPointer { o in vDSP_vrampmulD(i.baseAddress!, 1, &initialValue, &step, o.baseAddress!, 1, vDSP_Length(n)) } }
    }
    public static func formStereoRamp<U, V>(withInitialValue initialValue: inout Double, multiplyingBy multiplierOne: U, _ multiplierTwo: U, increment: Double,
                                            results resultOne: inout V, _ resultTwo: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        var step = increment
        let n = min(multiplierOne.count, multiplierTwo.count, resultOne.count, resultTwo.count); guard n > 0 else { return }
        multiplierOne.withUnsafeBufferPointer { i0 in multiplierTwo.withUnsafeBufferPointer { i1 in
            resultOne.withUnsafeMutableBufferPointer { o0 in resultTwo.withUnsafeMutableBufferPointer { o1 in
                vDSP_vrampmul2D(i0.baseAddress!, i1.baseAddress!, 1, &initialValue, &step, o0.baseAddress!, o1.baseAddress!, 1, vDSP_Length(n))
            } } } }
    }
    public static func stereoRamp<U>(withInitialValue initialValue: inout Double, multiplyingBy multiplierOne: U, _ multiplierTwo: U, increment: Double)
        -> (firstOutput: [Double], secondOutput: [Double]) where U: AccelerateBuffer, U.Element == Double {
        let n = min(multiplierOne.count, multiplierTwo.count)
        var a = [Double](repeating: 0, count: n), b = [Double](repeating: 0, count: n)
        formStereoRamp(withInitialValue: &initialValue, multiplyingBy: multiplierOne, multiplierTwo, increment: increment, results: &a, &b)
        return (a, b)
    }
