    public static func hypot<R, S, T, U, V>(x0: R, x1: S, y0: T, y1: U, result: inout V)
        where R: AccelerateBuffer, S: AccelerateBuffer, T: AccelerateBuffer, U: AccelerateBuffer, V: AccelerateMutableBuffer,
              R.Element == Double, S.Element == Double, T.Element == Double, U.Element == Double, V.Element == Double {
        let n = min(x0.count, x1.count, y0.count, y1.count, result.count); guard n > 0 else { return }
        x0.withUnsafeBufferPointer { a in y0.withUnsafeBufferPointer { b in x1.withUnsafeBufferPointer { c in y1.withUnsafeBufferPointer { d in
            result.withUnsafeMutableBufferPointer { e in
                vDSP_vpythgD(a.baseAddress!, 1, b.baseAddress!, 1, c.baseAddress!, 1, d.baseAddress!, 1, e.baseAddress!, 1, vDSP_Length(n))
            } } } } }
    }
