        where R: AccelerateBuffer, S: AccelerateBuffer, T: AccelerateBuffer, U: AccelerateBuffer, R.Element == Double, S.Element == Double, T.Element == Double, U.Element == Double {
        _array(min(x0.count, x1.count, y0.count, y1.count)) { hypot(x0: x0, x1: x1, y0: y0, y1: y1, result: &$0) }
    }
