    public static func integrate<U, V>(_ vector: U, using rule: IntegrationRule, stepSize: Double = 1, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        var h = stepSize
        let n = min(vector.count, result.count); guard n > 0 else { return }
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            switch rule {
            case .runningSum: vDSP_vrsumD(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            case .simpson: vDSP_vsimpsD(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            case .trapezoidal: vDSP_vtrapzD(a.baseAddress!, 1, &h, c.baseAddress!, 1, vDSP_Length(n))
            }
        } }
    }
