    public static func normalize(_ vector: some AccelerateBuffer<Double>, result: inout some AccelerateMutableBuffer<Double>) -> (mean: Double, stdDev: Double) {
        var m: Double = 0, s: Double = 0
        let n = min(vector.count, result.count)
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            if n > 0 { vDSP_normalizeD(a.baseAddress!, 1, c.baseAddress!, 1, &m, &s, vDSP_Length(n)) } } }
        return (m, s)
    }
    public static func normalize(_ vector: some AccelerateBuffer<Double>) -> [Double] {
        var r = [Double](repeating: 0, count: vector.count)
        normalize(vector, result: &r)
        return r
    }
