    public static func threshold<U, V>(_ vector: U, to lowerBound: Double, with rule: ThresholdRule<Double>, result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        var b = lowerBound
        let n = min(vector.count, result.count); guard n > 0 else { return }
        vector.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { c in
            switch rule {
            case .clampToThreshold: vDSP_vthrD(a.baseAddress!, 1, &b, c.baseAddress!, 1, vDSP_Length(n))
            case .zeroFill: vDSP_vthresD(a.baseAddress!, 1, &b, c.baseAddress!, 1, vDSP_Length(n))
            case .signedConstant(let k): var k = k; vDSP_vthrscD(a.baseAddress!, 1, &b, &k, c.baseAddress!, 1, vDSP_Length(n))
            }
        } }
    }
    public static func threshold<U>(_ vector: U, to lowerBound: Double, with rule: ThresholdRule<Double>) -> [Double] where U: AccelerateBuffer, U.Element == Double {
        _array(vector.count) { threshold(vector, to: lowerBound, with: rule, result: &$0) }
    }
    /// y[n] = b0 x[n] + b1 x[n-1] + b2 x[n-2] - a1 y[n-1] - a2 y[n-2] (coefficients (b0, b1, b2, a1, a2)); the first two
    /// outputs are the initial state
    public static func twoPoleTwoZeroFilter<U, V>(_ source: U, coefficients: (Double, Double, Double, Double, Double), result: inout V)
        where U: AccelerateBuffer, V: AccelerateMutableBuffer, U.Element == Double, V.Element == Double {
        let n = min(source.count, result.count); guard n > 2 else { return }
        var c = [coefficients.0, coefficients.1, coefficients.2, coefficients.3, coefficients.4]
        source.withUnsafeBufferPointer { a in result.withUnsafeMutableBufferPointer { r in vDSP_deq22D(a.baseAddress!, 1, &c, r.baseAddress!, 1, vDSP_Length(n - 2)) } }
    }
    public static func twoPoleTwoZeroFilter<U>(_ source: U, coefficients: (Double, Double, Double, Double, Double)) -> [Double] where U: AccelerateBuffer, U.Element == Double {
        var r = [Double](repeating: 0, count: source.count)
        twoPoleTwoZeroFilter(source, coefficients: coefficients, result: &r)
        return r
    }
    public static func formWindow<V>(usingSequence sequence: WindowSequence, result: inout V, isHalfWindow: Bool) where V: AccelerateMutableBuffer, V.Element == Double {
        let w = window(ofType: Double.self, usingSequence: sequence, count: result.count, isHalfWindow: isHalfWindow)
        result.withUnsafeMutableBufferPointer { r in for i in 0..<min(r.count, w.count) { r[i] = w[i] } }
    }

